    "algorithms": [
      {
        "name": "Closure Operator Computation",
        "pseudocode": "cl(A) = \u2229{C \u2208 closed_sets : A \u2286 C}\nTime: O(k\u00b7n)"
      },
      {
        "name": "Fixed-Point Transport",
        "pseudocode": "For each P \u2208 Fix(cl_S):\n  B = f(P)\n  Check cl_T(B) = B\nTime: O(|Fix| \u00b7 k \u00b7 n)"
      },
      {
        "name": "Pressure Chain Bound",
        "pseudocode": "Input: chain P_0 \u2286 ... \u2286 P_n, Lipschitz K\nBy induction:\n  Base: p(P_0) - p(P_0) = 0 \u2264 0\n  Step: p(P_{k+1}) - p(P_0) \u2264 K + K\u00b7k = K\u00b7(k+1)\nOutput: p(P_n) - p(P_0) \u2264 K\u00b7n"
      },
      {
        "name": "Prime Spectrum Equivalence",
        "pseudocode": "Input: OrderIso e : Ideal R \u2243o Ideal S\nFor each prime I of R:\n  Map to e(I) in S\n  Verify e(I) is prime (by preservation hypothesis)\nConstruct bijection on prime spectra\nTime: O(|Spec(R)|)"
      },
      {
        "name": "Security Margin Pseudometric",
        "pseudocode": "d(P,Q) = |p(P) - p(Q)|\nVerify: d(P,P)=0, d(P,Q)=d(Q,P), d(P,R)\u2264d(P,Q)+d(Q,R)\nTime: O(1) per evaluation"
      }
    ],
